1	import type { Container } from "@harbor/dispatch/types";
2	
3	const SEGREGATION: Record<string, readonly string[]> = {
4	  "1": ["2.1", "3", "4.1", "5.1", "5.2", "8"],
5	  "2.1": ["1", "5.1"],
6	  "3": ["1", "5.1", "5.2"],
7	  "4.1": ["1", "5.1"],
8	  "5.1": ["1", "2.1", "3", "4.1"],
9	  "5.2": ["1", "3"],
10	  "8": ["1"],
11	};
12	
13	export function primaryClass(dgClass: string): string {
14	  return dgClass.trim().split(".")[0];
15	}
16	
17	export function mustSegregate(a: string, b: string): boolean {
18	  const left = SEGREGATION[primaryClass(a)] ?? [];
19	  const right = SEGREGATION[primaryClass(b)] ?? [];
20	  return left.includes(primaryClass(b)) || right.includes(primaryClass(a));
21	}
22	
23	export function adjacentConflicts(row: readonly Container[]): Array<[string, string]> {
24	  const out: Array<[string, string]> = [];
25	  for (let i = 1; i < row.length; i++) {
26	    const a = row[i - 1];
27	    const b = row[i];
28	    if (a.dgClass && b.dgClass && mustSegregate(a.dgClass, b.dgClass)) {
29	      out.push([a.id, b.id]);
30	    }
31	  }
32	  return out;
33	}
34

1	import assert from "node:assert/strict";
2	import { describe, test } from "node:test";
3	import { adjacentConflicts, mustSegregate, primaryClass } from "@harbor/dispatch/cargo/hazmat";
4	
5	describe("dangerous goods", () => {
6	  test("primary class", () => {
7	    assert.equal(primaryClass("4.1"), "4");
8	    assert.equal(primaryClass(" 3 "), "3");
9	  });
10	
11	  test("explosives and flammable liquids are segregated", () => {
12	    assert.equal(mustSegregate("1", "3"), true);
13	    assert.equal(mustSegregate("3", "1"), true);
14	  });
15	
16	  test("compatible classes may be stowed together", () => {
17	    assert.equal(mustSegregate("3", "8"), false);
18	    assert.equal(mustSegregate("9", "9"), false);
19	  });
20	
21	  test("a row reports its adjacent conflicts", () => {
22	    const row = [
23	      { id: "C1", lengthFt: 20 as const, cargoKg: 1, tareKg: 1, dgClass: "3" },
24	      { id: "C2", lengthFt: 20 as const, cargoKg: 1, tareKg: 1, dgClass: "1" },
25	      { id: "C3", lengthFt: 20 as const, cargoKg: 1, tareKg: 1 },
26	    ];
27	    assert.deepEqual(adjacentConflicts(row), [["C1", "C2"]]);
28	  });
29	});
