export function primaryClass(dgClass: string): string {
  const trimmed = dgClass.trim();
  // Class 1 divisions (1.1-1.6) are all explosives; every other class's
  // division (e.g. 5.1 oxidiser vs 5.2 organic peroxide) is a distinct
  // hazard identity used as-is in the segregation table.
  return trimmed.startsWith("1.") ? "1" : trimmed;
}

