test("primary class", () => {
  assert.equal(primaryClass("4.1"), "4.1");
  assert.equal(primaryClass("1.4"), "1");
  assert.equal(primaryClass(" 3 "), "3");
});

test("explosives and flammable liquids are segregated", () => {
  assert.equal(mustSegregate("1", "3"), true);
  assert.equal(mustSegregate("3", "1"), true);
});

test("explosives and oxidisers/organic peroxides are segregated", () => {
  assert.equal(mustSegregate("1", "5.1"), true);
  assert.equal(mustSegregate("5.1", "1"), true);
  assert.equal(mustSegregate("2.1", "5.1"), true);
  assert.equal(mustSegregate("5.2", "3"), true);
});

test("compatible classes may be stowed together", () => {
  assert.equal(mustSegregate("3", "8"), false);
  assert.equal(mustSegregate("8", "5.1"), false);
  assert.equal(mustSegregate("9", "9"), false);
});

